-- أول درس لكل عالم كان فارغًا (2026-11-25)

INSERT INTO lessons (subject_id, slug, title_ar, description_ar, content_ar, age_group, difficulty, duration_min, points, sort_order)
SELECT s.id, v.slug, v.title, v.descr, v.content, v.age, v.diff, v.mins, v.pts, 1
FROM subjects s
JOIN (VALUES
  ('languages', 'colors-in-english', 'الأَلْوَانُ بِالْإِنْجِلِيزِيَّةِ', 'نَتَعَلَّمُ أَسْمَاءَ خَمْسَةِ أَلْوَانٍ بِالْإِنْجِلِيزِيَّةِ',
   '<h2>الأَلْوَانُ بِالْإِنْجِلِيزِيَّةِ</h2><p>🔴 أَحْمَرُ = <b dir="ltr">Red</b> (رِد)</p><p>🔵 أَزْرَقُ = <b dir="ltr">Blue</b> (بْلُو)</p><p>🟢 أَخْضَرُ = <b dir="ltr">Green</b> (جْرِين)</p><p>🟡 أَصْفَرُ = <b dir="ltr">Yellow</b> (يِلُّو)</p><p>⚫ أَسْوَدُ = <b dir="ltr">Black</b> (بْلَاك)</p><p>انْظُرْ حَوْلَكَ، وَقُلِ اسْمَ لَوْنِ كُلِّ شَيْءٍ بِالْإِنْجِلِيزِيَّةِ!</p>',
   '6-8', 1, 5, 10),
  ('thinking', 'complete-the-pattern', 'أَكْمِلِ النَّمَطَ', 'نَكْتَشِفُ الشَّيْءَ الَّذِي يَتَكَرَّرُ',
   '<h2>أَكْمِلِ النَّمَطَ</h2><p>النَّمَطُ شَيْءٌ يَتَكَرَّرُ بِتَرْتِيبٍ ثَابِتٍ.</p><p>🔴 🔵 🔴 🔵 🔴 ... مَاذَا بَعْدَهَا؟ 🔵</p><p>🍎 🍎 🍌 🍎 🍎 🍌 🍎 🍎 ... مَاذَا بَعْدَهَا؟ 🍌</p><p>١، ٢، ٣، ٤، ... مَاذَا بَعْدَهَا؟ ٥</p><p>ابْحَثْ عَنِ الْجُزْءِ الَّذِي يَتَكَرَّرُ، ثُمَّ أَكْمِلْ!</p>',
   '3-5', 1, 5, 10),
  ('creativity', 'mixing-colors', 'خَلْطُ الْأَلْوَانِ', 'كَيْفَ نَصْنَعُ أَلْوَانًا جَدِيدَةً؟',
   '<h2>خَلْطُ الْأَلْوَانِ</h2><p>الْأَلْوَانُ الْأَسَاسِيَّةُ ثَلَاثَةٌ: الْأَحْمَرُ، الْأَصْفَرُ، الْأَزْرَقُ.</p><p>🔴 + 🟡 = 🟠 أَحْمَرُ وَأَصْفَرُ يَصْنَعَانِ الْبُرْتُقَالِيَّ.</p><p>🔵 + 🟡 = 🟢 أَزْرَقُ وَأَصْفَرُ يَصْنَعَانِ الْأَخْضَرَ.</p><p>🔴 + 🔵 = 🟣 أَحْمَرُ وَأَزْرَقُ يَصْنَعَانِ الْبَنَفْسَجِيَّ.</p><p>جَرِّبْ فِي «ارْسُمْ»: لَوِّنْ بِالْأَصْفَرِ، ثُمَّ ارْسُمْ فَوْقَهُ بِالْأَزْرَقِ!</p>',
   '6-8', 1, 5, 10),
  ('knowledge', 'solar-system', 'كواكب المجموعة الشمسية', 'نتعرف على كواكب المجموعة الشمسية الثمانية',
   '<h2>كواكب المجموعة الشمسية</h2><p>تدور حول الشمس ثمانية كواكب، بالترتيب من الأقرب إلى الأبعد:</p><p>عطارد، الزهرة، الأرض، المريخ، المشتري، زحل، أورانوس، نبتون.</p><p><b>عطارد</b> أقرب كوكب إلى الشمس.</p><p><b>الأرض</b> هي الكوكب الثالث، والكوكب الوحيد الذي نعرف أن عليه حياة.</p><p><b>المشتري</b> أكبر كواكب المجموعة الشمسية.</p><p><b>زحل</b> تحيط به حلقات جميلة من الجليد والصخور.</p>',
   '9-12', 2, 7, 15)
) AS v(subject, slug, title, descr, content, age, diff, mins, pts) ON v.subject = s.slug
ON CONFLICT (subject_id, slug) DO NOTHING;

INSERT INTO quiz_questions (lesson_id, question_ar, options, correct_idx, explanation_ar, sort_order)
SELECT l.id, v.q, v.o::jsonb, v.c, v.e, v.s
FROM lessons l
JOIN (VALUES
  ('colors-in-english', 'مَا مَعْنَى كَلِمَةِ Red؟', '["أَزْرَقُ","أَحْمَرُ","أَخْضَرُ"]', 1, 'Red تَعْنِي أَحْمَرَ.', 1),
  ('colors-in-english', 'كَيْفَ نَقُولُ «أَصْفَرُ» بِالْإِنْجِلِيزِيَّةِ؟', '["Yellow","Black","Blue"]', 0, 'أَصْفَرُ = Yellow.', 2),
  ('colors-in-english', 'لَوْنُ الْعُشْبِ بِالْإِنْجِلِيزِيَّةِ هُوَ:', '["Red","Green","Black"]', 1, 'الْعُشْبُ أَخْضَرُ = Green.', 3),
  ('complete-the-pattern', '🔴 🔵 🔴 🔵 🔴 ... مَاذَا بَعْدَهَا؟', '["🔴","🔵","🟢"]', 1, 'الْأَحْمَرُ ثُمَّ الْأَزْرَقُ يَتَكَرَّرَانِ.', 1),
  ('complete-the-pattern', '⭐ ⭐ 🌙 ⭐ ⭐ 🌙 ⭐ ⭐ ... مَاذَا بَعْدَهَا؟', '["⭐","🌙","☀️"]', 1, 'نَجْمَتَانِ ثُمَّ قَمَرٌ.', 2),
  ('complete-the-pattern', '٢، ٤، ٦، ... مَا الْعَدَدُ التَّالِي؟', '["٧","٨","١٠"]', 1, 'نَزِيدُ اثْنَيْنِ كُلَّ مَرَّةٍ: ٦ + ٢ = ٨.', 3),
  ('mixing-colors', 'أَحْمَرُ + أَصْفَرُ = ؟', '["بُرْتُقَالِيٌّ","أَخْضَرُ","بَنَفْسَجِيٌّ"]', 0, 'الْأَحْمَرُ وَالْأَصْفَرُ يَصْنَعَانِ الْبُرْتُقَالِيَّ.', 1),
  ('mixing-colors', 'كَيْفَ نَصْنَعُ اللَّوْنَ الْأَخْضَرَ؟', '["أَحْمَرُ + أَزْرَقُ","أَزْرَقُ + أَصْفَرُ","أَحْمَرُ + أَصْفَرُ"]', 1, 'الْأَزْرَقُ وَالْأَصْفَرُ يَصْنَعَانِ الْأَخْضَرَ.', 2),
  ('mixing-colors', 'كَمْ لَوْنًا أَسَاسِيًّا تَعَلَّمْنَا؟', '["اثْنَانِ","ثَلَاثَةٌ","خَمْسَةٌ"]', 1, 'الْأَحْمَرُ وَالْأَصْفَرُ وَالْأَزْرَقُ.', 3),
  ('solar-system', 'ما أقرب كوكب إلى الشمس؟', '["الأرض","عطارد","المريخ"]', 1, 'عطارد هو الأقرب إلى الشمس.', 1),
  ('solar-system', 'ما أكبر كواكب المجموعة الشمسية؟', '["زحل","المشتري","نبتون"]', 1, 'المشتري هو الأكبر.', 2),
  ('solar-system', 'ترتيب كوكب الأرض من الشمس هو:', '["الثاني","الثالث","الرابع"]', 1, 'عطارد ثم الزهرة ثم الأرض.', 3)
) AS v(slug, q, o, c, e, s) ON v.slug = l.slug
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.lesson_id = l.id);
